INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "孙氏（明宣宗孝恭章皇后）", "aliases": ["孝恭章皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "孙氏（明宣宗孝恭章皇后）由贵妃被立为皇后。", "biography": null, "status": "draft", "id": "15138702-a78a-5b56-ab98-4cb1f1b546f3"}, {"name": "陈懋", "aliases": ["宁阳侯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈懋以宁阳侯身份巡边阅兵。", "biography": null, "status": "draft", "id": "e5696099-627f-57a5-b989-87e71d1b2e68"}, {"name": "于谦", "aliases": ["于謙"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统14年（年号对照1449年）八月，于谦出任兵部尚书。", "biography": null, "status": "draft", "id": "3f189404-652f-5b32-9509-a7b9157c87b2"}, {"name": "朱见深", "aliases": ["明宪宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宪宗，天順8年（1464年）正月，朱见深即皇帝位。", "biography": null, "status": "draft", "id": "71fde383-1de5-538d-bb25-2cc9e4cc7d1c"}, {"name": "王振（明英宗朝宦官）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "王振（明英宗朝宦官）掌管司礼监。", "biography": null, "status": "draft", "id": "b348fa2c-6cc7-57f7-9f9b-3198d1f7128a"}, {"name": "陈镒", "aliases": ["陳鎰"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统10年（年号对照1445年）十月，陈镒从陕西被召回，出任右都御史。", "biography": null, "status": "draft", "id": "805d1f86-64c9-5275-bbe4-61d272bc6ee3"}, {"name": "石亨", "aliases": ["都督石亨"], "era": "明", "birth_year": null, "death_year": null, "description": "石亨奉命统领京营兵。", "biography": null, "status": "draft", "id": "9892b251-a863-5d74-9c23-727ee42a25de"}, {"name": "商辂", "aliases": ["商輅"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統14年（1449年）八月，商辂以翰林修撰身份入阁。", "biography": null, "status": "draft", "id": "a6a9b79a-e654-56d7-85ce-a79e61f4c5f2"}, {"name": "彭时", "aliases": ["彭時"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正統14年（1449年）八月，彭时以翰林修撰身份入阁。", "biography": null, "status": "draft", "id": "a42ac84b-3969-512b-b1c5-d8e41cbc0eda"}, {"name": "黄萧养", "aliases": ["黃蕭養"], "era": "明", "birth_year": null, "death_year": null, "description": "黄萧养在广东起事。", "biography": null, "status": "draft", "id": "8eaf5c16-b48d-54b4-96be-47c1c72cb61a"}, {"name": "孙祥", "aliases": ["孫祥"], "era": "明", "birth_year": null, "death_year": null, "description": "孙祥受命守紫荆关。", "biography": null, "status": "draft", "id": "2b6b6285-161e-537e-b261-80a822d78235"}, {"name": "罗通", "aliases": ["羅通"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰4年（年号对照1453年）七月，罗通出任右都御史。", "biography": null, "status": "draft", "id": "8b713aa6-3282-5804-9460-1b47ae38c9c2"}, {"name": "王骥", "aliases": ["王驥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，宣德9年（年号对照1434年）三月，王骥出任兵部尚书。", "biography": null, "status": "draft", "id": "4a558c65-f1f5-51f5-90df-5aa57564c8bb"}, {"name": "也先", "aliases": ["瓦剌太师也先"], "era": "明", "birth_year": null, "death_year": null, "description": "也先所部为明廷防备对象。", "biography": null, "status": "draft", "id": "d9af0d41-e6b4-5de2-9de3-32e0f8826f3c"}, {"name": "王复（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，成化元年（年号对照1465年）十月，王复出任兵部尚书。", "biography": null, "status": "draft", "id": "ddaec8e0-153f-5d3e-b905-8625f4e7e632"}, {"name": "赵荣（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）正月，赵荣出任工部尚书。", "biography": null, "status": "draft", "id": "527c6d46-ede3-59e9-9478-77debb454708"}, {"name": "脱脱不花（蒙古可汗）", "aliases": ["達達可汗", "脫脫不花"], "era": "明", "birth_year": null, "death_year": null, "description": "脱脱不花（蒙古可汗）派使者到明朝。", "biography": null, "status": "draft", "id": "f7bcab60-cf00-572b-bcd5-5a8d52d60f73"}, {"name": "杨洪（明代昌平伯）", "aliases": ["昌平伯楊洪"], "era": "明", "birth_year": null, "death_year": null, "description": "杨洪（明代昌平伯）任总兵官并率部进剿。", "biography": null, "status": "draft", "id": "3eccbb0e-225d-52ff-8fbf-cf5a9d047470"}, {"name": "耿九畴", "aliases": ["耿九疇"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）三月，耿九畴出任右都御史。", "biography": null, "status": "draft", "id": "72d75593-924e-5fc5-b5f5-4bf88dd1343a"}, {"name": "董兴", "aliases": ["都督同知董興"], "era": "明", "birth_year": null, "death_year": null, "description": "董兴任左副总兵并领兵出征。", "biography": null, "status": "draft", "id": "6e3a2e86-3a9b-5b27-ab61-34b1a35c9c2d"}, {"name": "吴氏（明宣宗贤妃）", "aliases": ["宣庙贤妃", "景帝吴太后"], "era": "明", "birth_year": null, "death_year": null, "description": "吴氏（明宣宗贤妃）由贤妃尊为皇太后。", "biography": null, "status": "draft", "id": "3f05f558-cc1d-5d3c-a972-c6e156b55ded"}, {"name": "汪氏（明景帝贞惠安和景皇后）", "aliases": ["郕王妃汪氏", "景帝汪皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "汪氏（明景帝贞惠安和景皇后）被立为皇后。", "biography": null, "status": "draft", "id": "e6dd358d-26d5-518b-952f-0d84b504fd0c"}, {"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱祁钰被封为郕王", "description": "宣德十年二月辛亥，明英宗朱祁镇封弟弟朱祁钰为郕王。", "start_year": 1435, "end_year": 1435, "time_original": "宣德十年二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b9ea162-7214-52e5-a4cc-43c6daa10a35"}, {"title": "土木之变，明军溃败，明英宗被俘", "description": "正统十四年八月壬戌，遭围困的明军在土木溃败，明英宗朱祁镇被俘。英国公张辅、驸马都尉井源、平乡伯陈怀等官员在此役遇难。本纪称死者数十万，《瓦剌传》记为死伤数十万。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6aaa36e5-3c1b-5dfc-8f9d-e0938b222af8"}, {"title": "朱祁钰开始监国", "description": "正统14年（年号对照1449年）八月，朱祁钰开始监国。", "start_year": 1449, "end_year": 1449, "time_original": "正统14年（年号对照1449年）八月；公元年核为1449年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "871ba9f1-3385-51f2-9fe6-6ca88ca8b474"}, {"title": "明廷将通州所储粮食运入京师", "description": "正统十四年八月丙寅，明廷下令把储存在通州的粮食运入京师。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "246d3d29-5ea5-5915-bc7b-93b4d89119cb"}, {"title": "明廷调兵入卫京师，召陈懋率部返回", "description": "正统十四年八月，明廷征调南北直隶、山东和河南担任防倭、运粮任务的部队入卫京师，并命宁阳侯陈懋率部返回。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c999698d-a432-5ed1-9760-f55da897dadf"}, {"title": "于谦出任兵部尚书", "description": "正统14年（年号对照1449年）八月，于谦出任兵部尚书。", "start_year": 1449, "end_year": 1449, "time_original": "正统14年（年号对照1449年）八月；公元年核为1449年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "0b43c06a-c557-5474-997b-8e1c0d034882"}, {"title": "明廷要求群臣直言时政、举荐人才", "description": "正统十四年八月，明廷命群臣直言当时的政务，举荐可供任用的人才。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0916e91f-caff-5d6e-936a-d5b531af0f5c"}, {"title": "皇太后命立朱见深为皇太子", "description": "正统十四年八月己巳，皇太后孙氏命立明英宗之子朱见深为皇太子。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f925d2ce-3044-591c-bfc8-92130e2031e9"}, {"title": "明廷下令抚恤阵亡将士", "description": "正统十四年八月，明廷下令抚恤此前作战阵亡的军官和士兵。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2973266a-9ed0-56f6-b15f-850489b15421"}, {"title": "明廷抄没王振家产", "description": "正统十四年八月庚午，明廷查抄并登记太监王振的家产。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3f4e9381-1023-5761-861b-d97125daa33c"}, {"title": "陈镒外出巡抚京畿地区", "description": "正统14年（年号对照1449年）八月，陈镒外出巡抚京畿地区。", "start_year": 1449, "end_year": 1449, "time_original": "正统14年（年号对照1449年）八月；公元年核为1449年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "d7cf34e6-d3aa-50e2-a3ab-b131e9cc2aae"}, {"title": "都督石亨奉命统领京营兵", "description": "正统十四年八月壬申，明廷令都督石亨总领驻京军队。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "213e4ac6-8acf-51a3-827d-db3ca87a4c45"}, {"title": "明廷要求边将谨慎应对瓦剌挟明英宗到来", "description": "正统十四年八月乙亥，明廷告诫边将，若瓦剌带着被俘的明英宗来到，守军不得轻率出城。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b46fef83-f4bb-5fcd-bc21-1fd5471d2da3"}, {"title": "明廷将南京军器运往京师", "description": "正统十四年八月，明廷下令将南京的军用器械运往京师。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b570a7f2-0672-54c5-a7d8-4a1b1ffe71e1"}, {"title": "商辂以翰林修撰身份入阁", "description": "正統14年（1449年）八月，商辂以翰林修撰身份入阁。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "bec1539a-1370-5534-a1fa-69edb50fcc52"}, {"title": "彭时以翰林修撰身份入阁", "description": "正統14年（1449年）八月，彭时以翰林修撰身份入阁。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "fae0f7f5-5c14-5b13-8179-39e5fed909bd"}, {"title": "黄萧养在广东起事", "description": "正统十四年八月，黄萧养在广东起事，反抗明廷。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4c76c31a-eedd-5a73-8137-abe84d43fbe4"}, {"title": "朱祁钰即皇帝位", "description": "正統14年（1449年）九月，朱祁钰即皇帝位。", "start_year": 1449, "end_year": 1449, "time_original": "正統14年（1449年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "0e9436c8-a4f3-542e-be05-34f0ec94d382"}, {"title": "明景帝遥尊明英宗为太上皇帝", "description": "正统十四年九月癸未，朱祁钰即位，当日遥尊仍在瓦剌军中的明英宗朱祁镇为太上皇帝。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d0ea6b59-d5ae-57e1-a320-e48ca748eb55"}, {"title": "明景帝命次年改元景泰", "description": "正统十四年九月癸未，朱祁钰即位，命次年使用景泰年号。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fe63b506-00f7-58b8-989e-0761dae6d554"}, {"title": "景帝即位颁大赦，预减景泰二年田租三成", "description": "正统十四年九月癸未，明景帝即位后大赦天下，并下令减免景泰二年应交田租的三成。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f6c9e255-a31c-55b0-ad16-9435cf8f8c44"}, {"title": "明廷处死王振族人", "description": "正统十四年九月甲申，明廷处死宦官王振的族人。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5fabb031-bf59-5857-8907-8ae877899046"}, {"title": "本纪记处州一带的起事被平定", "description": "正统十四年九月庚寅，《景帝本纪》记处州一带的起事被明廷平定。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "648a839b-eb0e-5baa-95ff-3278f59bb421"}, {"title": "季铎奉皇太后之命向太上皇传达消息", "description": "正统十四年九月癸巳，指挥佥事季铎奉皇太后之命，向身在瓦剌军中的太上皇传达消息。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d8bcfc7a-7cb5-52d4-a1dd-0f54a0d606b5"}, {"title": "明廷祭奠宣府和土木阵亡将士并安葬遗骸", "description": "正统十四年九月甲午，明廷祭奠在宣府和土木阵亡的将士，并安葬他们的遗骸。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2eb5bb58-d142-50d1-966c-ad78c6d0cf2a"}, {"title": "张安在广州战败阵亡，王清被俘身亡", "description": "正统十四年九月乙未，总兵官安乡伯张安率军征讨广州的起事者，战败阵亡。指挥佥事王清被俘后身亡。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "44c93d67-f161-54ab-a787-78872ae7149a"}, {"title": "孙祥和罗通受命守紫荆关和居庸关", "description": "正统十四年九月辛丑，朝廷任命给事中孙祥、郎中罗通为右副都御史，分别镇守紫荆关和居庸关。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d23aa19c-01cb-5fcd-9150-9cf83f1b0fee"}, {"title": "明廷派十五名御史赴京畿、山东、山西和河南募兵", "description": "正统十四年九月甲辰，朝廷派十五名御史赴京畿和山东、山西、河南招募士兵。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c868c274-d243-59f8-b6c8-32233ec1a50c"}, {"title": "陈友领兵征讨湖广和贵州起事苗民", "description": "正统十四年九月，明廷派都督同知陈友率军征讨湖广和贵州起事的苗民。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5189331-985e-5570-b40b-2c6ab1b1c9ae"}, {"title": "明廷派使者送信给太上皇", "description": "正统十四年九月乙巳，明廷派遣使者送信给太上皇朱祁镇。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dcf0a166-136b-5676-8b94-b78a6eefd3c8"}, {"title": "平越卫被围，明廷派滇蜀部队与王骥会合", "description": "正统十四年九月丙午，起事苗民围攻平越卫。明廷调云南、四川的军队与王骥会合，前往征讨。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a53f2a1b-bb41-5634-b6ab-ab2107e4438f"}, {"title": "杨信民出任右佥都御史，奉命征讨广东起事者", "description": "正统十四年九月，朝廷任命参议杨信民为右佥都御史，派他征讨广东的起事者。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4da68eb5-38ca-502b-bfdc-9f3d6be4ed13"}, {"title": "也先带太上皇朱祁镇来到大同", "description": "正统十四年十月戊申，瓦剌太师也先带着被俘的太上皇朱祁镇来到大同。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5eb57077-201c-597b-b20b-612daeede7b1"}, {"title": "明景帝下诏征召诸王援助朝廷", "description": "正统十四年十月壬子，明景帝下诏，令各地藩王出兵援助朝廷。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cdc98671-3824-574a-a0cd-8e13d203ccce"}, {"title": "于谦提督各营，石亨等分守京城九门", "description": "正统十四年十月乙卯，明廷命于谦提督各营，石亨和各将分守京城九门。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7c011220-9244-552a-afa4-76c768ad078c"}, {"title": "瓦剌攻陷紫荆关，孙祥阵亡，京师戒严", "description": "正统十四年十月丙辰，瓦剌太师也先率部攻陷紫荆关，守将孙祥阵亡，京师进入戒严。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3613a1e-9306-59ee-a767-1f760c66e71c"}, {"title": "明廷命宣府、辽东等地兵力入援京师", "description": "正统十四年十月丁巳，朝廷令宣府、辽东的总兵官，山东、河南、山西、陕西的巡抚，以及负责募兵的御史率兵入援京师。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a16070d6-aff9-5748-a1b7-7e8ae9fa91c4"}, {"title": "瓦剌军逼近京城，明军在彰义门击败来军", "description": "正统十四年十月戊午，瓦剌太师也先率部逼近京城，都督高礼、毛福寿在彰义门击败瓦剌军。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6159dc06-6606-591a-826c-929ac46a27df"}, {"title": "王复、赵荣出使也先军营，在土城拜见太上皇", "description": "正统十四年十月己未，右通政王复与太常少卿赵荣出使瓦剌太师也先的军营，在土城拜见太上皇朱祁镇。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e388db22-76d9-56ef-9c8a-dcb31bd519d6"}, {"title": "明廷向朝鲜征兵，调河州诸卫土军入援", "description": "正统十四年十月庚申，明廷向朝鲜征求兵力，并调河州各卫的当地军队入援京师。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3bfbff87-b80c-526c-a69f-49d88ba46a72"}, {"title": "于谦、石亨等在京城外连续击败瓦剌军", "description": "正统十四年十月，于谦、石亨等率明军在京师城下连续击败也先所部。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5a2bbe8f-a07c-527c-8434-9a0208bbbc5f"}, {"title": "瓦剌军从京城外撤退", "description": "正统十四年十月壬戌，围攻京师的瓦剌部队撤退。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "630e791d-1941-5909-8963-8163cea532ed"}, {"title": "撤退的瓦剌部队出紫荆关", "description": "正统十四年十月甲子，已经从京师撤退的瓦剌部队出紫荆关。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b0a38532-031b-56a2-86e1-bd2ceabdb082"}, {"title": "明廷下令停止诸王军队入援", "description": "正统十四年十月丁卯，瓦剌撤退后，明廷下诏停止征召各地藩王军队入援。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c395ec38-7f0f-51b6-8224-3f52cd61533b"}, {"title": "脱脱不花派使者到明朝", "description": "正统十四年十月，本纪记脱脱不花派使者到明朝。原文称他为“瓦剌可汗”，《鞑靼传》称他为蒙古可汗、也先为太师。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d76c862e-dcc2-5c49-a631-02efc18b1ff5"}, {"title": "杨洪任总兵官，与孙镗、范广清剿京畿余部", "description": "正统十四年十月辛未，明廷任命昌平伯杨洪为总兵官，命都督孙镗、范广为副手，征剿仍在京畿的敌军余部。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9f07207c-6528-5167-8345-f7b2e3c6374a"}, {"title": "明廷下令整修边境关隘", "description": "正统十四年十一月癸未，明廷着手整修沿边关隘。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十一月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2af2adf3-2784-52d7-9eed-219651b876e7"}, {"title": "毛福寿受命任副总兵，征讨辰州起事苗民", "description": "正统十四年十一月辛卯，明廷任命毛福寿为副总兵，派他征讨辰州起事的苗民。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十一月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a385aa81-f48a-51e0-aa1d-f0d0957260d6"}, {"title": "太上皇朱祁镇抵达瓦剌", "description": "正统十四年十一月壬辰，被俘的太上皇朱祁镇被带到瓦剌。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十一月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "46cf7a5e-3238-51cb-ac35-5d5885fab080"}, {"title": "耿九畴奉命安抚南直隶流民，明廷给予三年赋役减免", "description": "正统十四年十一月乙未，明廷派侍郎耿九畴安抚南直隶流民，给予三年赋役减免。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十一月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c45fa3fa-f72d-5613-80d9-99f7f17c4264"}, {"title": "景帝尊皇太后孙氏为上圣皇太后", "description": "正统十四年十二月庚戌，朱祁钰加尊皇太后孙氏，徽号为上圣皇太后。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96012dab-05d8-57d0-9271-c14692647919"}, {"title": "王骥任平蛮将军、总兵官，征讨贵州起事苗民", "description": "正统十四年十二月辛亥，明廷任王骥为平蛮将军、总兵官，率兵征讨贵州起事的苗民。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9f938dda-6974-533b-b11b-72bab058f0b6"}, {"title": "董兴领兵征讨广东起事者，孟鉴参赞军务", "description": "正统十四年十二月，明廷任都督同知董兴为左副总兵，领兵征讨广东起事者，命户部侍郎孟鉴参赞军务。 按原历纪年，事情发生在公元1449至1450年之间。", "start_year": null, "end_year": null, "time_original": "正统十四年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c0de03b5-f95a-58ea-9a15-9a9d64fa96e3"}, {"title": "景帝尊生母吴贤妃为皇太后", "description": "正统十四年十二月癸丑，明景帝朱祁钰尊生母吴贤妃为皇太后。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十二月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b656ca65-2970-52df-8226-f25cc9b6ea14"}, {"title": "景帝立汪氏为皇后", "description": "正统十四年十二月甲寅，明景帝立郕王时的王妃汪氏为皇后。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十二月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "943c7c59-18c7-55f2-8a56-53e88d6c950d"}, {"title": "明景帝下令大赦", "description": "正统十四年十二月丙辰，明景帝下令大赦。", "start_year": 1450, "end_year": 1450, "time_original": "正统十四年十二月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f93a00af-c99e-57fe-9097-3cd1486a35b6"}, {"title": "石亨、杨洪和柳溥分别操练京营兵", "description": "正统十四年十二月己未，明廷令石亨、杨洪、柳溥分别率领并操练京城各营的部队。", "start_year": 1450, "end_year": 1450, "time_original": "正统十四年十二月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "266c8e5e-7661-5eb0-8239-d3d211bfc1ec"}, {"title": "明廷在西直门外祭奠阵亡官军", "description": "正统十四年十二月戊辰，明廷在京师西直门外祭奠阵亡军官和士兵。", "start_year": 1450, "end_year": 1450, "time_original": "正统十四年十二月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "48bfbc3f-f4f2-5a2a-b4a4-738dc6863fc9"}, {"title": "本纪汇记琉球中山等地入贡", "description": "正统十四年，琉球中山、占城、乌斯藏和撒马儿罕入贡。 按原历纪年，事情发生在公元1449至1450年之间。", "start_year": null, "end_year": null, "time_original": "正统十四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2bc491d8-a6fa-54ce-a58a-bc9541a0e934"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
